import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Key Decisions","description":"Product and engineering judgments that Hearth has settled and should not reverse casually.","frontmatter":{"title":"Key Decisions","description":"Product and engineering judgments that Hearth has settled and should not reverse casually.","outline":false},"headers":[],"relativePath":"en/reference/decisions.md","filePath":"en/reference/decisions.md","lastUpdated":1794305977000}'),n={name:"en/reference/decisions.md"};function s(d,e,i,c,l,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="key-decisions" tabindex="-1">Key Decisions <a class="header-anchor" href="#key-decisions" aria-label="Permalink to &quot;Key Decisions&quot;">​</a></h1><p class="lead">These judgments define the product boundary and implementation direction. Evidence can revise them, but daily development should not quietly bypass them. When a disagreement appears, first check whether the conclusion itself has changed, not just the wording.</p><table tabindex="0"><thead><tr><th>Decision</th><th>Conclusion</th><th>Main impact</th></tr></thead><tbody><tr><td>Product shape</td><td>Single-user, self-hosted, local-first personal Agent OS</td><td>No enterprise multi-tenancy; data stays in the user&#39;s environment by default</td></tr><tr><td>Core object</td><td>Tasks rather than chat history</td><td>Interfaces organize around task cards, approvals, artifacts, and recovery</td></tr><tr><td>Source of truth</td><td>Record facts first; interfaces, indexes, and notifications are projections</td><td>State survives refreshes, device changes, and crashes</td></tr><tr><td>Write model</td><td>One write authority per state root</td><td>Early system uses one process, one writer, and a local database</td></tr><tr><td>Execution</td><td>Durable work with retry, pause, checkpoints, and takeover</td><td>Long tasks survive restarts, sleep, and network loss</td></tr><tr><td>System structure</td><td>Modular monolith before microservices</td><td>Boundaries are enforced by interfaces, tests, and permissions</td></tr><tr><td>Executors</td><td>Multiple specialized executors routed by capability, risk, and cost</td><td>No single model is asked to do everything</td></tr><tr><td>Codex position</td><td>A high-capability external executor, not the product</td><td>Hearth retains tasks, authority, verification, memory, and receipts</td></tr><tr><td>External action</td><td>Preview, authorize, execute, then reconcile</td><td>Sends, writes, deletes, publishes, and payments are not blindly retried</td></tr><tr><td>Goal completion</td><td>Goal contract plus evidence-driven completion judgement</td><td>Model self-assessment, executor exit, or UI state cannot close a goal-backed task</td></tr><tr><td>Delegation and handoff</td><td>Single-layer delegation; child work and handoffs may only narrow authority</td><td>Handoff packets carry generations, and old results cannot overwrite newer state</td></tr><tr><td>Safety</td><td>Least privilege, short-lived credentials, isolation, default-deny network</td><td>Models and executors never see long-lived raw credentials</td></tr><tr><td>Personal context</td><td>Personal ontology, Context Packs, and attention budgets</td><td>Context carries provenance, sensitivity, budget, and interruption cost; conflicts stay visible</td></tr><tr><td>Memory and evolution</td><td>Correctable, forgettable memory; evaluated, canaried, reversible methods</td><td>No unbounded self-modification and no self-expanded authority</td></tr><tr><td>Acceptance</td><td>Real tasks, independent verification, human time, recovery, and cost</td><td>A demo or model self-assessment does not prove capability</td></tr><tr><td>Evaluation ownership</td><td>The evaluation stack is standalone in <code>hearth-eval</code>; the main repository keeps only the bridge</td><td>Product automated tests cannot masquerade as real experiments or pass rates</td></tr><tr><td>Connection runtime</td><td>Transport, subscription, freshness, and execution ownership are separate, with generation fencing</td><td>Offline actions enter the outbox; old connections cannot write or advance state</td></tr><tr><td>Mobile</td><td>Phone focuses on approval, review, takeover, and simple starts</td><td>It does not duplicate every desktop management feature</td></tr><tr><td>Explicit non-goals</td><td>Enterprise multi-tenancy, public agent marketplace, unapproved high-risk automation</td><td>The product remains focused and personally controllable</td></tr></tbody></table><p><strong>Why these choices.</strong> The central problem is not whether a model is smart enough. It is whether long work can be authorized, verified, recovered, and explained. If task state exists only in a chat transcript, users cannot tell which step truly finished or resume after failure. Fact records, a single writer, and durable execution are therefore foundations, not later optimizations.</p><p>Multiple executors exist because work has different boundaries. General reasoning suits short understanding. Codex suits code, long documents, and complex workspaces. Connectors suit systems with official interfaces. Browsers and desktop operation cover software without interfaces. Document and data processing suit deterministic tools. Value judgments and accountability remain with people. Routing optimizes success, latency, and cost only after permission, risk, and reversibility are satisfied.</p><p>Memory and method evolution must be slow. Memory directly affects judgment, so a wrong fact causes repeated rework. Method changes can expand system capability or quietly expand authority. Both need provenance, evaluation, canary use, and rollback; one successful demo does not prove long-term value.</p><p><strong>Delivery judgment.</strong> Hearth does not build the whole backend before the interface. Every phase delivers a complete path: the user sees a result, state is persisted, execution leaves evidence, failures recover, and external actions are approved and reconciled. Phase 1 delivers the smallest complete MVP, followed by the six-phase route for broader work, proactive service, memory, and multiple devices.</p><p>Hearth&#39;s moat is not a stronger model. It is knowing when not to call a model, how much context an executor should receive, who must authorize an action, how to prove completion, how to recover from failure, what to remember, what to forget, and when to stop and return attention to the user.</p>',8)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
